Here's a Python program that meets your requirements. This program uses a dictionary to store the phonebook and provides the specified functionality.

```python
# Initialize the phonebook as an empty dictionary
phonebook = {}

def add_contact(name, phone_number):
    """Add a new contact to the phonebook with the given name and phone number."""
    if name in phonebook:
        print(f"Contact already exists for {name}. Updating phone number.")
    else:
        phonebook[name] = phone_number
        print(f"Contact added: {name} {phone_number}")

def remove_contact(name):
    """Remove a contact from the phonebook with the given name."""
    if name in phonebook:
        del phonebook[name]
        print(f"Contact removed: {name}")
    else:
        print(f"Contact {name} not found.")

def update_contact(name, new_phone_number):
    """Update a contact's phone number in the phonebook with the given name."""
    if name in phonebook:
        phonebook[name] = new_phone_number
        print(f"Contact updated: {name} {new_phone_number}")
    else:
        print(f"Contact {name} not found.")

def search_contact(name):
    """Search for a contact in the phonebook with the given name and return their phone number."""
    if name in phonebook:
        print(f"Contact found: {name} {phonebook[name]}")
    else:
        print(f"Contact {name} not found.")

# Main program loop
while True:
    user_input = input("Enter a command (add, remove, update, search, or exit): ").lower()

    if user_input == "add":
        name = input("Enter name: ")
        phone_number = input("Enter phone number: ")
        add_contact(name, phone_number)

    elif user_input == "remove":
        name = input("Enter name: ")
        remove_contact(name)

    elif user_input == "update":
        name = input("Enter name: ")
        new_phone_number = input("Enter new phone number: ")
        update_contact(name, new_phone_number)

    elif user_input == "search":
        name = input("Enter name: ")
        search_contact(name)

    elif user_input == "exit":
        print("Exiting phonebook...")
        break

    else:
        print("Invalid command. Please try again.")
```

This program will continue to run until the user types "exit" and will provide the specified output for each command.
